function main(): void {
  const s = "abc";
  console.log(s[1]);
  console.log(s[10]);
  console.log(s[10] === undefined, s[0] !== undefined, s[-1], s[1.5]);
  const i = 2;
  console.log(s[i] ?? "dflt", s[i + 5] ?? "dflt");
  let n = 0;
  for (let k = 0; k < s.length; k++) { if (s[k] === "b") n++; }
  console.log(n, s[0] + s[2]);
}
